public static string Describe(object shape) => shape switch {
    Circle { Radius: > 0 } c => $"Circle with area: {Math.PI * c.Radius * c.Radius:F2}",
    Rectangle r when r.Width == r.Height => $"Square of side {r.Width}",
    Rectangle r => $"Rectangle {r.Width}x{r.Height}",
    _ => "Unknown shape",
};

public static T RequireNotNull<T>(T? value, [CallerArgumentExpression(nameof(value))] string? paramName = null) {
    return value ?? throw new ArgumentNullException(paramName);
}

public async IAsyncEnumerable<int> GenerateSequenceAsync([EnumeratorCancellation] CancellationToken ct = default) {
    for (int i = 0; i < 100; i++) {
        await Task.Delay(50, ct);
        yield return i;
    }
}

public readonly record struct Money(decimal Amount, string Currency) {
    public static Money Zero(string currency) => new(0m, currency);
    public static Money operator +(Money a, Money b) {
        if (a.Currency != b.Currency) throw new InvalidOperationException("Currency mismatch");
        return new Money(a.Amount + b.Amount, a.Currency);
    }
}

var channel = Channel.CreateBounded<WorkItem>(new BoundedChannelOptions(100) {
    FullMode = BoundedChannelFullMode.Wait
});

Task producer = Task.Run(async () => {
    for (int i = 0; i < 50; i++) await channel.Writer.WriteAsync(new WorkItem(i));
    channel.Writer.Complete();
});

public static async Task<T> TimeoutAfter<T>(this Task<T> task, TimeSpan timeout) {
    using var cts = new CancellationTokenSource();
    var completedTask = await Task.WhenAny(task, Task.Delay(timeout, cts.Token));
    if (completedTask == task) {
        cts.Cancel();
        return await task;
    }
    throw new TimeoutException("The operation timed out.");
}

